<?php
declare(strict_types=1);namespace Joomleague\Module\VenueProgram\Site\Helper;defined('_JEXEC')or die;use Joomla\CMS\Factory;use Joomla\Database\DatabaseInterface;use Joomla\Registry\Registry;use Joomleague\Component\Joomleague\Domain\Service\ProgrammeReader;use Joomleague\Component\Joomleague\Domain\Service\VenueSummaryReader;
final class VenueProgramHelper{/** @return array<string,mixed> */public function getProgram(Registry$p):array{$id=(int)$p->get('venue_id',0);if($id<1)return['error'=>'MOD_JOOMLEAGUE_VENUE_PROGRAM_NOT_CONFIGURED'];$app=Factory::getApplication();$app->bootComponent('com_joomleague');$lang=Factory::getLanguage();$lang->load('com_joomleague',JPATH_SITE)||$lang->load('com_joomleague',JPATH_SITE.'/components/com_joomleague');$levels=$app->getIdentity()->getAuthorisedViewLevels();$db=Factory::getContainer()->get(DatabaseInterface::class);try{$venue=(new VenueSummaryReader($db))->read($id,$levels);if(isset($venue['error']))return['error'=>'MOD_JOOMLEAGUE_VENUE_PROGRAM_UNAVAILABLE'];$items=(new ProgrammeReader($db))->forVenue($id,$levels);}catch(\Throwable){return['error'=>'MOD_JOOMLEAGUE_VENUE_PROGRAM_UNAVAILABLE'];}$mode=(string)$p->get('mode','upcoming');$now=Factory::getDate()->toUnix();$items=array_values(array_filter($items,static function(array$item)use($mode,$now):bool{$time=$item['scheduled_start']===null?null:Factory::getDate($item['scheduled_start'],'UTC')->toUnix();return match($mode){'completed'=>$item['played'], 'all'=>true, default=>!$item['played']&&$time!==null&&$time>=$now};}));if($mode==='completed')usort($items,static fn(array$a,array$b):int=>strcmp((string)$b['scheduled_start'],(string)$a['scheduled_start'])?:$b['id']<=>$a['id']);$limit=max(1,min(50,(int)$p->get('limit',5)));return['venue'=>$venue['venue'],'items'=>array_slice($items,0,$limit)];}}
